  font-family: Georgia, 'Times New Roman', serif;
  background-color: #f4f9f0;
  color: #2c3e2a;
  max-width: 640px;
  margin: 3rem auto;
  padding: 0 1.5rem;
  line-height: 1.6;
}

h1 {
  color: #3a7d44;
  border-bottom: 3px solid #8fbf8f;
  padding-bottom: 0.4rem;
